mapper.update:
UPDATE task
SET title = #{title}, description = #{description}, assignee_id = #{assigneeId}, parent_id = #{parentId},
    importance = #{importance}, urgency = #{urgency}, plan_days = #{planDays}, est_hours = #{estHours},
    required_skills = #{requiredSkills,typeHandler=org.miniteam.pms.common.mybatis.JsonStringListTypeHandler},
    plan_start = #{planStart}, due_date = #{dueDate}
WHERE id = #{id}

UPDATE task
SET status = #{status}, progress = #{progress}, actual_start = #{actualStart}, actual_end = #{actualEnd},
    sort_order = #{sortOrder}
WHERE id = #{id}
